prs.body:
It was doing something like this:
```js
"use server";
export const foo = async function bar() {
    return 'exported named function expression';
};
ensureServerEntryExports([
    bar, // should be foo!
]);
registerServerReference(bar, "003c8ed39a99caf636869d076cc7cae786a4053164", null); // shoudl be foo!
```

leading to
```
⨯ ReferenceError: quux is not defined
    at module evaluation (test/development/app-dir/source-mapping/app/actions1.ts:15:35)
    at module evaluation (test/development/app-dir/source-mapping/app/page.tsx:2:1)
  13 | }
  14 |
> 15 | export const qux = async function quux() {
     |                                   ^
  16 |   return 'exported named function expression'
  17 | }
  18 | {
  page: '/'
}
```

This will eventually allow better tree shaking

Before:
```js
const $$RSC_SERVER_CACHE_0_INNER = async function cached() {
  return expensive()
}

export var $$RSC_SERVER_CACHE_0 = reactCache(function cached() {
  return cache('default', id, 0, $$RSC_SERVER_CACHE_0_INNER, [])
})

registerServerReference($$RSC_SERVER_CACHE_0, id, null)
Object.defineProperty($$RSC_SERVER_CACHE_0, 'name', { value: 'cached' })
```

After:
```js
const $$RSC_SERVER_CACHE_0_INNER = async function cached() {
  return expensive()
}

export var $$RSC_SERVER_CACHE_0 =
	/*#__PURE__*/Object.defineProperty(
	/*#__PURE__*/registerServerReference(
	/*#__PURE__*/reactCache(function cached() {
		return cache('default', id, 0, $$RSC_SERVER_CACHE_0_INNER, [])
	}), id, null), 'name', { value: 'cached' })
```
